package com.example.tripUpdates.model.entity;

import com.example.tripUpdates.model.enums.EventType;
import com.fasterxml.jackson.databind.JsonNode;
import jakarta.persistence.*;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;
import java.time.LocalDateTime;
import java.util.UUID;

/**
 * Archives critical events (STATUS_CHANGE, SOS) for audit trails.
 * Location updates are deliberately omitted to conserve storage.
 * Events are generated by Redis with sequence numbers for ordering guarantees.
 */
@Entity
@Table(name = "event_archive",
        uniqueConstraints = @jakarta.persistence.UniqueConstraint(name = "uk_event_archive_trip_seq",
                columnNames = {"trip_id", "sequence_number"}),
        indexes = {
        @Index(name = "idx_event_archive_trip_id", columnList = "trip_id"),
        @Index(name = "idx_event_archive_event_type", columnList = "event_type")
})
public class EventArchive {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    @JdbcTypeCode(SqlTypes.UUID)
    @Column(columnDefinition = "UUID")
    private UUID id;

    @Column(name = "trip_id", nullable = false, columnDefinition = "UUID")
    @JdbcTypeCode(SqlTypes.UUID)
    private UUID tripId;

    @Enumerated(EnumType.STRING)
    @Column(name = "event_type", nullable = false)
    private EventType eventType;

    @Column(name = "sequence_number", nullable = false)
    private long sequenceNumber;

    // Use Hibernate 6 native JSON mapping
    @JdbcTypeCode(SqlTypes.JSON)
    @Column(name = "payload", columnDefinition = "jsonb")
    private JsonNode payload;

    @Column(name = "created_at", nullable = false, updatable = false)
    private LocalDateTime createdAt;

    public EventArchive() {}

    public EventArchive(String tripId, EventType eventType, long sequenceNumber, JsonNode payload) {
        this.id = UUID.randomUUID();
        this.tripId = UUID.fromString(tripId);
        this.eventType = eventType;
        this.sequenceNumber = sequenceNumber;
        this.payload = payload;
        this.createdAt = LocalDateTime.now();
    }

    public UUID getId() {
        return id;
    }

    public void setId(UUID id) {
        this.id = id;
    }

    public UUID getTripId() {
        return tripId;
    }

    public void setTripId(UUID tripId) {
        this.tripId = tripId;
    }

    public EventType getEventType() {
        return eventType;
    }

    public void setEventType(EventType eventType) {
        this.eventType = eventType;
    }

    public long getSequenceNumber() {
        return sequenceNumber;
    }

    public void setSequenceNumber(long sequenceNumber) {
        this.sequenceNumber = sequenceNumber;
    }

    public JsonNode getPayload() {
        return payload;
    }

    public void setPayload(JsonNode payload) {
        this.payload = payload;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(LocalDateTime createdAt) {
        this.createdAt = createdAt;
    }
}